#include <iostream>
#include <string>
#include <stack>
using namespace std;

int main() {
    int m;
    if (!(cin >> m)) return 0;
    stack<long long> st, minSt;

    while (m--) {
        string op;
        cin >> op;
        if (op == "push") {
            long long x;
            cin >> x;
            st.push(x);
            if (minSt.empty()) minSt.push(x);
            else minSt.push(min(x, minSt.top()));
        } else if (op == "pop") {
            if (st.empty()) { cout << "error\n"; continue; }
            cout << st.top() << "\n";
            st.pop();
            minSt.pop();
        } else if (op == "top") {
            if (st.empty()) { cout << "error\n"; continue; }
            cout << st.top() << "\n";
        } else if (op == "getMin") {
            if (st.empty()) { cout << "error\n"; continue; }
            cout << minSt.top() << "\n";
        }
    }
    return 0;
}
